    val vsetky: List<Hra> by lazy {
        val a = JSONArray(DATA)
        (0 until a.length()).map { i ->
            val o = a.getJSONObject(i)
            val k = o.getJSONArray("k")
            Hra(o.getString("i"), o.getString("t"), o.getString("n"), (0 until k.length()).map { k.getString(it) })
        }
    }

    fun najdi(id: String): Hra? = vsetky.firstOrNull { it.id == id }
